export function llmPointer(read: LlmRead): Record<string, unknown> | undefined {
  if (!read.artifact) return undefined;
  const a = read.artifact.analysis;
  return {
    provenance: 'LLM',
    model: read.artifact.model,
    stale: read.stale,
    confidence: a.confidence,
    purpose: a.purpose ?? '',
  };
}

